
/* Kydno Kore — Duel Flips */

window.DuelFlips = window.DuelFlips || {};

window.DuelFlips.loadDuelFlips = async function () {
    const list = document.getElementById("duel-active-flips-list");
        const count = document.getElementById("duel-flips-count");

            if (!list) return;

                list.innerHTML = `
                        <div class="flips-empty-state">
                                    <p>Loading Duel Flips...</p>
                                            </div>`;

                                                const { data: duels, error } = await window.supabaseClient
                                                        .from("duel_flips")
                                                                .select("id, host_id, host_side, start_mode, status, target_value, created_at")
                                                                        .eq("status", "waiting")
                                                                                .order("created_at", { ascending: false });

                                                                                    if (error) {
                                                                                            console.error("Error loading Duel Flips:", error);
                                                                                                    list.innerHTML = `
                                                                                                                <div class="flips-empty-state">
                                                                                                                                <h3>Couldn't load Duel Flips</h3>
                                                                                                                                                <p>Please try again shortly.</p>
                                                                                                                                                            </div>`;
                                                                                                                                                                    if (count) count.textContent = "0 active";
                                                                                                                                                                            return;
                                                                                                                                                                                }

                                                                                                                                                                                    list.innerHTML = "";

                                                                                                                                                                                        if (count) count.textContent = `${duels.length} active`;

                                                                                                                                                                                            if (!duels.length) {
                                                                                                                                                                                                    list.innerHTML = `
                                                                                                                                                                                                                <div class="flips-empty-state">
                                                                                                                                                                                                                                <div class="flips-empty-icon">⚔️</div>
                                                                                                                                                                                                                                                <h3>No Active Duel Flips</h3>
                                                                                                                                                                                                                                                                <p>There aren't any duel flips available right now.</p>
                                                                                                                                                                                                                                                                            </div>`;
                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                            const { data: { user } } =
                                                                                                                                                                                                                                                                                                    await window.supabaseClient.auth.getUser();

                                                                                                                                                                                                                                                                                                        duels.forEach((duel) => {
                                                                                                                                                                                                                                                                                                                const card = document.createElement("div");
                                                                                                                                                                                                                                                                                                                        card.className = "active-flip-card";

                                                                                                                                                                                                                                                                                                                                card.innerHTML = `
                                                                                                                                                                                                                                                                                                                                            <div style="padding:16px;">
                                                                                                                                                                                                                                                                                                                                                            <h3>Duel Flip</h3>
                                                                                                                                                                                                                                                                                                                                                                            <p>Host side: <strong>${
                                                                                                                                                                                                                                                                                                                                                                                                duel.host_side === "tails" ? "Tails" : "Heads"
                                                                                                                                                                                                                                                                                                                                                                                                                }</strong></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                <p>Target value: <strong>${
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Number(duel.target_value || 0).toLocaleString()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }</strong></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        duel.start_mode === "manual"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? "Manual start"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : "Auto start"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p>Players: 1/4</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (user?.id === duel.host_id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const note = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    note.textContent = "You created this duel";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                note.style.padding = "0 16px 16px";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            card.appendChild(note);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            list.appendChild(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /* =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   DUEL CREATION MODAL CONTROLS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ========================= */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.addEventListener("DOMContentLoaded", function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const openButton = document.getElementById("create-duel-flip-button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const modal = document.getElementById("create-duel-modal");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const closeButton = document.getElementById("close-create-duel");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const sideButtons = document.querySelectorAll(".duel-side-option");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const modeButtons = document.querySelectorAll(".duel-mode-option");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const confirmButton = document.getElementById("confirm-create-duel");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const message = document.getElementById("duel-create-message");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!openButton || !modal) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error("Duel creation modal or Create Duel button not found.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let selectedSide = "heads";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  let selectedMode = "auto";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function updateChoices() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              sideButtons.forEach(function (button) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const selected = button.dataset.side === selectedSide;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      button.style.outline = selected ? "2px solid #60a5fa" : "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  button.style.background = selected ? "#174b91" : "#263244";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              button.style.color = "white";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          button.style.padding = "10px 16px";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      button.style.borderRadius = "8px";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      modeButtons.forEach(function (button) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const selected = button.dataset.mode === selectedMode;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              button.style.outline = selected ? "2px solid #60a5fa" : "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          button.style.background = selected ? "#174b91" : "#263244";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      button.style.color = "white";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  button.style.padding = "10px 16px";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              button.style.borderRadius = "8px";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function openModal() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      modal.classList.remove("hidden");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (message) message.textContent = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      updateChoices();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function closeModal() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      modal.classList.add("hidden");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              openButton.addEventListener("click", openModal);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (closeButton) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          closeButton.addEventListener("click", closeModal);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  modal.addEventListener("click", function (event) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (event.target === modal) closeModal();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sideButtons.forEach(function (button) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          button.addEventListener("click", function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      selectedSide = button.dataset.side;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  updateChoices();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  modeButtons.forEach(function (button) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          button.addEventListener("click", function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      selectedMode = button.dataset.mode;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  updateChoices();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Keep the choices available for the next implementation step.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      window.DuelFlips.creationChoices = function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          hostSide: selectedSide,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      startMode: selectedMode
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Creating a duel will be connected after inventory selection is implemented.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (confirmButton) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  confirmButton.addEventListener("click", function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (message) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              message.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "Pet selection and duel creation aren't connected yet.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              updateChoices();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              